export function translateBato(value, isRTL) {
  if (!isRTL || typeof value !== "string") return value;
  return BATO_AR[value.trim().replace(/\s+/g, " ")] || value;
}
export function useBatoText() {
  const { isRTL } = useLocation();
  return value => translateBato(value, isRTL);
}
